def solution(grid_str):
    n, m = map(int, grid_str.split('\n')[0].split())
    grid = [list(line) for line in grid_str.split('\n')[1:n+1]]

    if n == 0 or m == 0:
        return '\n'.join(''.join(row) for row in grid)

    visited = [[False] * m for _ in range(n)]
    changed = 0

    # Directions for connectivity
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Function to get bounding box of a connected component
    def get_bounding_box(start_r, start_c):
        min_r, max_r, min_c, max_c = start_r, start_r, start_c, start_c
        cells = [(start_r, start_c)]

        q = [(start_r, start_c)]
        visited[start_r][start_c] = True

        while q:
            r, c = q.pop(0)
            min_r, max_r, min_c, max_c = min(min_r, r), max(max_r, r), min(min_c, c), max(max_c, c)

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc]:
                    if grid[nr][nc] == '.':
                        visited[nr][nc] = True
                        cells.append((nr, nc))
                        q.append((nr, nc))
                    elif grid[nr][nc] == '*':
                        # Mark wall as changed (will become free) if it's within bounding box of a valid expansion
                        # We'll handle this in another pass
                        pass

        return min_r, max_r, min_c, max_c, set(cells)

    # Track walls to remove
    walls_to_remove = set()

    # Process each cell
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # Start BFS to find this connected component
                component = []
                q = [(i, j)]
                visited[i][j] = True

                while q:
                    r, c = q.pop(0)
                    component.append((r, c))

                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc]:
                            if grid[nr][nc] == '.':
                                visited[nr][nc] = True
                                q.append((nr, nc))
                            elif grid[nr][nc] == '*':
                                # Consider removing wall if it helps form rectangle
                                walls_to_remove.add((nr, nc))

                if not component:
                    continue

                # Find bounding box
                min_r, max_r, min_c, max_c = n, -1, m, -1
                for r, c in component:
                    min_r = min(min_r, r)
                    max_r = max(max_r, r)
                    min_c = min(min_c, c)
                    max_c = max(max_c, c)

                # Check if component is already a rectangle
                is_rectangle = True
                expected_cells = (max_r - min_r + 1) * (max_c - min_c + 1)
                if len(component) != expected_cells:
                    # Check if the bounding box exactly matches the component
                    for r in range(min_r, max_r + 1):
                        for c in range(min_c, max_c + 1):
                            if not ((r, c) in component):
                                is_rectangle = False
                                break
                        if not is_rectangle:
                            break

                if not is_rectangle:
                    # Mark all cells in bounding box as free
                    for r in range(min_r, max_r + 1):
                        for c in range(min_c, max_c + 1):
                            if grid[r][c] == '*':
                                grid[r][c] = '.'
                                walls_to_remove.add((r, c))

    return '\n'.join(''.join(row) for row in grid)

# Solution for Petya's lucky region problem

def generate_lucky_numbers(limit):
    """Generate all lucky numbers (only digits 4 and 7) up to limit."""
    lucky = []
    def dfs(current):
        if current > limit:
            return
        if current > 0:
            lucky.append(current)
        if current * 4 <= limit:
            dfs(current * 4)
        if current * 7 <= limit:
            dfs(current * 7)

    dfs(0)  # 0 is a placeholder
    lucky = [x for x in lucky if x > 0]
    lucky.sort()
    return lucky

