            adj[u].append(v)
            adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(size)

    # Generate lucky numbers up to n
    lucky_numbers = generate_lucky_numbers(n)
    lucky_set = set(lucky_numbers)

    # Check if any component is already lucky
    for size in component_sizes:
        if size in lucky_set:
            return "0"

    # Find minimum roads needed
    # Sort component sizes for efficient checking
    component_sizes.sort()

    # Try merging smallest number of components first
    num_components = len(component_sizes)

    # Start with 2 components (1 road), 3 components (2 roads), etc.
    for num_to_merge in range(2, min(num_components + 1, 13)):  # Practical limit
        target_roads = num_to_merge - 1
        found = False

        # Try all combinations of num_to_merge components
        # Using recursion to find combinations
        def find_combination(start, count, current_sum):
            nonlocal found, target_roads
            if found:
                return

            if count == 0:
                if current_sum in lucky_set:
                    found = True
                return

            # Optimization: if we need current elements and they can reach target
            remaining = count - 1
            for i in range(start, num_components - remaining + 1):
                if not found:
                    find_combination(i + 1, remaining, current_sum + component_sizes[i])

        find_combination(0, num_to_merge, 0)

        if found:
            return str(target_roads)

    # If we can't form any lucky number by merging
    return "-1"

