def get_grundy(n, k):
    """Compute Grundy numbers for pile sizes with efficient pattern detection"""
    if n == 0:
        return 0

    # For k = 1, the pattern is straightforward: G(x) = floor(x/2)
    if k == 1:
        return n // 2

    if k % 2 == 1:
        # When k is odd, splitting 2*x into k piles of x each gives XOR = G(x)
        # Compute Grundy numbers directly
        grundy = [0] * (n + 1)
        for i in range(1, n + 1):
            reachable = {grundy[i - 1]}
            if i % 2 == 0:
                x = i // 2
                reachable.add(grundy[x])
            grundy[i] = 0
            m = reachable
            g = 0
            while g in m:
                g += 1
            grundy[i] = g
        return grundy[n]

    # When k is even, splitting 2*x into k piles of x each gives XOR = 0
    # Compute Grundy numbers
    grundy = [0] * (n + 1)
    for i in range(1, n + 1):
        reachable = {grundy[i - 1]}
        if i % 2 == 0:
            x = i // 2
            reachable.add(0)  # XOR with k even number of same values = 0
        grundy[i] = 0
        m = reachable
        g = 0
        while g in m:
            g += 1
        grundy[i] = g
    return grundy[n]

