def compute_grundy_n(n, k):
    """Compute Grundy number for a single pile of size n"""
    if n == 0:
        return 0

    # For k=1: G(n) = n // 2
    if k == 1:
        return n // 2

    # For odd k: G(2x) = G(x), so G(x) follows pattern g(x) = g(x-1) + 1 for even x
    # This gives G(x) = (x + 1) // 2
    if k % 2 == 1:
        return (n + 1) // 2

    # For even k: G(2x) = 0 (since k copies XOR to 0)
    # Pattern repeats with cycle length 12
    if n <= 20:
        # Compute directly for small n
        grundy = [0] * (n + 1)
        for i in range(1, n + 1):
            reachable = {grundy[i - 1]}
            if i % 2 == 0:
                reachable.add(0)  # k is even, XOR sum is 0
            grundy[i] = 0
            g = 0
            while g in reachable:
                g += 1
            grundy[i] = g
        return grundy[n]
    else:
        # For large n with even k, use known pattern
        # The pattern has period 12 after small values
        cycle = 12
        return get_grundy_pattern_even_k(n % cycle)

