def is_gp(sequence):
    """Check if sequence is a geometric progression"""
    n = len(sequence)
    if n <= 2:
        return True

    # Count zeros to handle special cases
    zeros = [i for i, x in enumerate(sequence) if x == 0]

    if len(zeros) == n:
        return True

    # If first element is 0, the common ratio must be handled specially
    if sequence[0] == 0 and sequence[1] == 0:
        # All zeros from start, check if any non-zero breaks pattern
        first_nonzero = -1
        for i, x in enumerate(sequence):
            if x != 0:
                first_nonzero = i
                break

        if first_nonzero == -1:  # All zeros
            return True

        # After the first non-zero element, all must be zeros
        if first_nonzero > 1:
            return False

        # Check ratio consistency for the remaining part
        ratio = None
        for i in range(first_nonzero + 1, n):
            if sequence[i] == 0:
                return False  # Non-zero after zero pattern is invalid
        return True

    # First element should not be zero unless it's the all-zeros case
    if sequence[0] == 0:
        return sequence[1] == 0 and all(x == 0 for x in sequence[2:])

    # Compute ratio from first two elements
    if sequence[1] != 0:
        ratio = sequence[1] / sequence[0]
    else:
        # sequence[0] != 0, sequence[1] == 0 -> ratio is 0
        ratio = 0

    for i in range(2, n):
        if sequence[i] != sequence[i-1] * ratio:
            return False

    return True


def remove_element(sequence, index):
    """Remove element at index and return new sequence"""
    return sequence[:index] + sequence[index+1:]


