def solution(input_str):
    """
    Solves the Stable Roommates problem using Li's algorithm.
    Returns the matching as N lines, each with the partner city (1-indexed), or -1 if impossible.
    """
    lines = input_str.strip().split('\n')
    if not lines or not lines[0].strip():
        return "-1\n"

    try:
        n = int(lines[0])
    except ValueError:
        return "-1\n"

    if n % 2 != 0:
        return "-1\n"  # Odd number of cities can't be paired

    # Parse costs - line i has costs from city i to all other cities
    costs = []
    for i in range(n):
        if i + 1 >= len(lines):
            return "-1\n"
        parts = list(map(int, lines[i + 1].split()))
        costs.append(parts)

    # Build complete cost matrix for convenience
    # costs[i][j] = cost from city i (0-indexed) to city j (0-indexed)
    adj = [[0] * n for _ in range(n)]
    for i in range(n):
        idx = 0
        for j in range(n):
            if j == i:
                continue
            # In input, for line i: skip position i
            adj[i][j] = costs[i][idx]

            idx += 1
            if j <= i - 1:
                idx -= 1

    # Create preference lists (lower cost = higher preference)
    preferences = []
    for i in range(n):
        prefs = [(costs[i][j], j) for j in range(n) if j != i]
        prefs.sort()  # Sort by cost
        preferences.append([p[1] for p in prefs])  # Just the city indices

    # Li's algorithm for stable roommates matching
    matched = [-1] * n  # matched[i] = city j paired with i

    # Phase 1: Check if a stable matching exists
    while True:
        # Build tentative matching
        if all(m != -1 for m in matched):
            break

        # Try to find a stable matching using the standard algorithm
        proposal_list = []

        for _ in range(n * n):
            changed = False
            for proposer in range(n):
                if matched[proposer] != -1:
                    continue

                # Propose to first available in preference list
                pref = preferences[proposer]
                for candidate in pref:
                    if matched[candidate] == -1:
                        matched[proposer] = candidate
                        matched[candidate] = proposer
                        changed = True
                        break
                    elif matched[candidate] == proposer:
                        continue
                    else:
                        # candidate is matched, check if they prefer proposer
                        cur = matched[candidate]
                        if preferences[candidate].index(proposer) < preferences[candidate].index(cur):
                            matched[proposer] = candidate
                            matched[candidate] = proposer
                            matched[cur] = -1
                            changed = True
                        break

            if not changed:
                break

        if not all(m != -1 for m in matched):
            break

        # Check for blocking pairs
        stable = True
        for i in range(n):
            for j in range(i + 1, n):
                # Check if (i, j) is a blocking pair
                if matched[i] != -1 and matched[j] != -1:
                    continue
                # One or both should be matched for blocking
                if matched[i] == -1 or matched[j] == -1:
                    continue

                p = preferences[i]
                q = preferences[j]

                # For i: does j come before current match?
                if i != matched[j]:
                    if q.index(j) < q.index(matched[i]):
                        if p.index(i) < p.index(matched[j]):
                            stable = False
                            break
                    if p.index(i) < p.index(matched[j]):
                        if q.index(j) < q.index(matched[i]):
                            stable = False
                            break

        if stable:
            break

    if not all(m != -1 for m in matched):
        return "-1\n"

    # Verify and return result
    result = []
    for i in range(n):
        result.append(str(matched[i] + 1))

    return "\n".join(result) + "\n"

