    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse the cost matrix
    # Line 1 has N-1 values (costs for city 1), line 2 has N-1 values (costs for city 2), etc.
    costs = [[0] * (n - 1) for _ in range(n)]

    for i in range(n):
        line = lines[1 + i].split()
        # The values are for X=1, X=i+1, X=i+2, ..., X=N, but skipping X=i
        # So position 0 is cost to city 1, position 1 is cost to city 2, etc.
        # We need to map position to actual city index
        for j, cost in enumerate(line):
            actual_j = j if j < i else j + 1  # skip the current city
            costs[i][actual_j] = int(cost)

    # For efficiency, transpose costs[i] to include all j including i (cost to self = infinity)
    full_costs = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                full_costs[i][j] = costs[i][j]

    def is_stable(matching):
        """Check if a matching is stable (no two cities prefer each other over their current partners)"""
        # Check all pairs of cities
        for i in range(n):
            if matching[i] == -1:
                continue
            current_partner = matching[i]
            for j in range(i + 1, n):
                if matching[j] == -1:
                    continue
                if j == current_partner:
                    continue
                # Check if i would prefer j over current_partner
                if full_costs[i][j] < full_costs[i][current_partner]:
                    # And if j would prefer i over current_partner
                    if full_costs[j][i] < full_costs[j][matching[j]]:
                        return False
        return True

    def backtrack(idx, matching, used):
        if idx == n:
            return is_stable(matching)

        # Try to pair city 'idx' with someone not yet used
        for j in range(idx + 1, n):
            if not used[j]:
                matching[idx] = j
                matching[j] = idx
                used[j] = True

                if backtrack(idx + 1, matching, used):
                    return True

                # Backtrack
                matching[idx] = -1
                matching[j] = -1
                used[j] = False

        return False

    matching = [-1] * n
    used = [False] * n

    if backtrack(0, matching, used):
        return '\n'.join(str(matching[i] + 1) for i in range(n)) + '\n'
    else:
        return '-1\n'

