    components = []

    for i in range(n):
        if not visited[i]:
            comp = [i]
            visited[i] = True
            stack = [i]
            while stack:
                curr = stack.pop()
                for neighbor in adj[curr]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
                        comp.append(neighbor)
            components.append(comp)

