            passed = False
            for _ in range(r - 1):
                x = pow(x, 2, n)
                if x == n - 1:
                    passed = True
                    break
            if not passed:
                return False
        return True

    # Count primes p where p = 2 or p ≡ 1 (mod 4)
    for i in range(l, r + 1):
        if is_prime(i) and (i == 2 or i % 4 == 1):
            count += 1

    return str(count) + '\n'

