import math
from functools import reduce
from itertools import combinations

def gcd_list(lst):
    """Compute GCD of a list of numbers"""
    if not lst:
        return 0
    return reduce(math.gcd, lst)

def max_divisor(val, k):
    """Find the largest divisor of val that is <= k"""
    if val <= k:
        return val
    # Search from k down to 1 for largest divisor
    for d in range(k, 1, -1):
        if val % d == 0:
            return d
    return 1

def can_achieve_gcd_1(selected_indices, k, a):
    """Check if selecting these judges allows achieving final GCD = 1"""
    n = len(a)
    final_vals = []

    for i in range(n):
        if i in selected_indices:
            d = max_divisor(a[i], k)
            final_vals.append(a[i] // d if d > 1 else a[i])
        else:
            final_vals.append(a[i])

    return gcd_list(final_vals) == 1

