def solution(input_str):
    if not input_str:
        return "NO\n"

    lines = input_str.strip().split('\n')
    if not lines:
        return "NO\n"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "NO\n"

    clauses = []
    for i in range(n):
        parts = list(map(int, lines[1 + i].split()))
        clauses.append(parts[1:])

    # Build data structures
    var_clauses = defaultdict(list)  # variable -> list of (clause_idx, literal)

    for i, clause in enumerate(clauses):
        for lit in clause:
            var_clauses[abs(lit) - 1].append((i, lit))

    assignment = [0] * m  # -1 unassigned, 0 false, 1 true

    def is_satisfied():
        """Check if all clauses are satisfied"""
        for i, clause in enumerate(clauses):
            if not any(lit > 0 and assignment[abs(lit)-1] == 1 or 
                      lit < 0 and assignment[abs(lit)-1] == 0 
                      for lit in clause):
                return False
        return True

    def backtrack(idx, progress):
        """Backtracking solver with conflict handling"""
        if is_satisfied():
            return True, assignment.copy()

        if idx >= m:
            return False, [0] * m

        # Find an unsatisfied clause and a variable to assign
        unsat_msg = None
        for i, clause in enumerate(clauses):
            if not any(lit > 0 and assignment[abs(lit)-1] == 1 or 
                      lit < 0 and assignment[abs(lit)-1] == 0 
                      for lit in clause):
                unsat_msg = (i, clause)
                break

        if unsat_msg is None:
            return True, assignment.copy()

        clause_idx, unsat_clause = unsat_msg

        # Find variables that appear in this clause
        clause_vars = [abs(lit) - 1 for lit in unsat_clause]

        # Get already assigned literals in this clause
        lit_values = [(lit, assignment[abs(lit)-1]) for lit in unsat_clause 
                      if assignment[abs(lit)-1] != 0]

        # If already satisfied, move to next variable
        if lit_values:
            return backtrack(idx + 1, progress)

        # Try to satisfy clause by assigning variables not yet assigned
        assigned_vars = [v for v in clause_vars if assignment[v] != 0]
        remaining_vars = [v for v in clause_vars if assignment[v] == 0]

        if not remaining_vars:
            return False, [0] * m

        # Try assigning each remaining variable
        for var_idx in remaining_vars:
            # Give this literal to satisfy the clause
            lit = unsat_clause[0]

            # Assign value to satisfy this literal
            new_val = 1 if lit > 0 else 0

            # Check if this conflicts with already assigned vars in same clause
            valid = True
            for other_lit in unsat_clause:
                if assignment[abs(other_lit) - 1] != 0:
                    other_val = 1 if other_lit > 0 else 0
                    if lit == other_lit and new_val != other_val:
                        valid = False
                    elif lit == -other_lit and new_val != other_val:
                        valid = False

            if valid:
                assignment[var_idx] = new_val
                success, result = backtrack(idx + 1, progress)
                if success:
                    return True, result
                assignment[var_idx] = 0  # backtrack

        return False, [0] * m

    success, final_assignment = backtrack(0, 0)

    if success:
        return "YES\n" + "".join(map(str, final_assignment))
    else:
        return "NO\n"


