import sys

# Mocking input retrieval for testing
class MockInput:
    def __init__(self, content):
        self.content = content
        self.lines = content.strip().split('\n')
        self.idx = 0

    def readline(self):
        if self.idx < len(self.lines):
            result = self.lines[self.idx]
            self.idx += 1
            return result
        return ""

def get_input():
    return sys.stdin.read()

# Solution function for pytest integration
def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "0\n"
    n = int(lines[0])
    # We don't actually need array values since the answer only depends on n
    a = list(map(int, lines[1].split())) if len(lines) > 1 else []

    MOD = 10**9 + 7

    ans = 0

    for r1 in range(1, n + 1):
        l1_l2_count = (r1 - 1) * r1 // 2
        r2_count = n - r1

        if l1_l2_count > 0 and r2_count > 0:
            contrib = (l1_l2_count % MOD) * (r2_count % MOD)
            ans = (ans + contrib) % MOD

    return f"{ans}\n"

