def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    l, r = map(int, lines[1].split())

    results = []

    for x1 in range(1, n + 1):
        found = False
        best_tuple = None

        # y1 must satisfy: l <= x1 * y1 <= r
        # So y1 >= ceil(l/x1) and y1 <= min(m, floor(r/x1))
        y1_min = (l + x1 - 1) // x1
        y1_max = min(m, r // x1)

        if y1_min <= y1_max:
            for y1 in range(y1_min, y1_max + 1):
                P = x1 * y1

                # Find x2 > x1 such that x2 divides P and gives valid y2
                # x2 must be <= n
                for x2 in range(x1 + 1, min(n, P) + 1):
                    if P % x2 == 0:
                        y2 = P // x2
                        # Check if y2 < y1 and y2 >= 1 (y2 < y1 is guaranteed if x2 > x1)
                        if y2 < y1:
                            found = True
                            best_tuple = (x1, y1, x2, y2)
                            break

                if found:
                    break

        if found:
            results.append(f"{best_tuple[0]} {best_tuple[1]} {best_tuple[2]} {best_tuple[3]}")
        else:
            results.append("-1")

    return '\n'.join(results)

def solution(input_str):
    input_str = input_str.strip()
    lines = input_str.split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    output_pieces = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        a = []
        for i in range(n):
            row = list(map(int, lines[idx].split()))
            a.append(row)
            idx += 1

        ops = lines[idx]
        idx += 1

        # Process each operation
        for op in ops:
            if op == 'R':
                # Shift columns right: position j gets value from (j-1) % n
                row = a[0]
                for _ in range(n):
                    new_row = [row[(j - 1) % n] for j in range(n)]
                    del a[0]
                    a.insert(0, new_row)
            elif op == 'L':
                # Shift columns left: position j gets value from (j+1) % n
                row = a[0]
                for _ in range(n):
                    new_row = [row[(j + 1) % n] for j in range(n)]
                    del a[0]
                    a.insert(0, new_row)
            elif op == 'D':
                # Shift rows down: row i gets value from (i-1) % n
                row = a[0]
                for _ in range(n):
                    new_row = row[:]
                    a.insert(0, new_row)
                    del a[0]
                    row = new_row
            elif op == 'U':
                # Shift rows up: row i gets value from (i+1) % n
                row = a[0]
                for _ in range(n):
                    new_row = row[:]
                    a.append(new_row)
                    del a[-2]
                    row = new_row
            elif op == 'I':
                # Inverse each row
                for i in range(n):
                    inv = [0] * n
                    for j in range(n):
                        inv[a[i][j] - 1] = j + 1
                    for j in range(n):
                        a[i][j] = inv[j]
            elif op == 'C':
                # Inverse each column
                for j in range(n):
                    inv = [0] * n
                    for i in range(n):
                        inv[a[i][j] - 1] = i + 1
                    for i in range(n):
                        a[i][j] = inv[i]

        # Format output
        result_lines = [' '.join(map(str, row)) for row in a]
        output_pieces.append('\n'.join(result_lines))

    return '\n\n'.join(output_pieces)

from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    k = list(map(int, lines[1].split()))

    type_offers = defaultdict(list)
    for i in range(m):
        d, t = map(int, lines[2 + i].split())
        type_offers[t].append(d)

    def check(D):
        # Assign each item to a buying day
        day_spending = defaultdict(int)

        for i in range(n):
            t = i + 1
            valid_days = [d for d in type_offers[t] if d <= D]

            if valid_days:
                # For types with sale opportunity, buy all on the latest sale day
                d = max(valid_days)
                day_spending[d] += k[i]
            else:
                # For types without sale opportunity, buy at regular price on day D
                day_spending[D] += 2 * k[i]

        # Check daily constraints: cumulative spending must not exceed the day number
