    MAX = 2 * k + 1

    # dp[i][diff + offset] = True if state is reachable
    dp = [[False] * MAX for _ in range(n + 1)]
    # parent[i][diff + offset] = (prev_diff + offset, move_char) for backtracking
    parent = [[None] * MAX for _ in range(n + 1)]

    dp[0][offset] = True

    for i in range(n):
        for d in range(-k, k + 1):  # difference from -k to k
            if not dp[i][d + offset]:
                continue

            # Determine possible moves based on character
            if s[i] == 'W':
                moves = [(d + 1, 'W')]
            elif s[i] == 'L':
                moves = [(d - 1, 'L')]
            else:  # 'D' or '?'
                moves = [(d, 'D')]
                if s[i] == '?':
                    moves.append((d + 1, 'W'))
                    moves.append((d - 1, 'L'))

            for nd, m in moves:
                # Check if next difference is valid
                if abs(nd) > k:
                    continue

                is_last = (i == n - 1)

                if is_last:
                    # At end position, must be exactly k
                    if abs(nd) == k:
                        if not dp[i + 1][nd + offset]:
                            dp[i + 1][nd + offset] = True
                            parent[i + 1][nd + offset] = (d + offset, m)
                else:
                    # At intermediate position, must be strictly less than k
                    if abs(nd) < k:
                        if not dp[i + 1][nd + offset]:
                            dp[i + 1][nd + offset] = True
                            parent[i + 1][nd + offset] = (d + offset, m)

    # Backtrack from a valid terminal state
    for target in [k, -k]:
        if dp[n][target + offset]:
            result = []
            curr = target
            for i in range(n, 0, -1):
                prev, m = parent[i][curr + offset]
                result.append(m)
                curr = prev - offset

            return ''.join(result[::-1]) + '\n'

    return "NO\n"


