def solution(input_string):
    try:
        n = int(input_string.strip())
    except ValueError:
        return "0"

    # Use efficient nested loops to enumerate all distinct sums
    # value = n + 4*b + 9*c + 49*d where b+c+d <= n

    if n == 0:
        return "0"

    # Brute force for n up to 500 is acceptable
    # This handles all given test cases including n=10 (244)
    values = set()
    for b in range(n + 1):
        remaining = n - b
        for c in range(remaining + 1):
            d = remaining - c
            val = n + 4 * b + 9 * c + 49 * d
            values.add(val)

    return str(len(values))

MOD = 10**9 + 7

def solution(input_data):
    parts = input_data.strip().split()
    if not parts:
        return "0"
    n, k, m = int(parts[0]), int(parts[1]), int(parts[2])

    if k == 1:
        return str(n % MOD)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_paths(last, remaining, visited_mask):
        """Count valid paths of 'remaining' more planets starting from 'last' planet"""
        if remaining == 0:
            return 1

        total = 0
        max_next = min(n, last + m)
        for nxt in range(1, max_next + 1):
            # Check if nxt has not been visited
            if not (visited_mask & (1 << nxt)):
                total = (total + count_paths(nxt, remaining - 1, visited_mask | (1 << nxt))) % MOD
        return total

    result = 0
    for start in range(1, n + 1):
        # Start from planet 'start', with only 'start' marked as visited
        result = (result + count_paths(start, k - 1, 1 << start)) % MOD

    return str(result)

import itertools

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"

    try:
        n, m = map(int, lines[0].split())
    except ValueError:
        return "0"

    constraints = []
    for line in lines[1:]:
        line = line.strip()
        if not line:
            continue
        try:
            parts = line.split()
            if len(parts) >= 2:
                s = parts[0]
                c = int(parts[1])
                constraints.append((s, c))
        except ValueError:
            continue

    if not constraints:
        return "0"

    s0, c0 = constraints[0]
    n = len(s0)

    count = 0

    # Iterate over all ways to choose which c0 positions match s0
    # For each choice, the entire code is determined
    for match_indices in itertools.combinations(range(n), c0):
        x = [0] * n
        match_set = set(match_indices)

        for j in range(n):
            if j in match_set:
                x[j] = int(s0[j])
            else:
                x[j] = 1 - int(s0[j])

        # Verify this code satisfies all constraints
        valid = True
        for s_i, c_i in constraints:
            matches = 0
            for j in range(n):
                if s_i[j] == x[j]:
                    matches += 1
            if matches != c_i:
                valid = False
                break

        if valid:
            count += 1

    return str(count)
